'use client';

import { Children, isValidElement, useCallback, useLayoutEffect, useRef, type JSX, type ReactNode, type Ref } from 'react';
import { Button as RACButton, composeRenderProps, type ButtonProps as RACButtonProps } from 'react-aria-components';
import styles from './button.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

export type ButtonVariant = 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'link';
export type ButtonSize = 'sm' | 'md' | 'lg' | 'icon';

interface ButtonBaseProps extends Omit<RACButtonProps, 'aria-label' | 'aria-labelledby'> {
  /** Visual style. `primary` for the one main action in a view; `danger` for destructive actions. */
  variant?: ButtonVariant;
  ref?: Ref<HTMLButtonElement>;
}

/** `size="icon"` renders a square button with no visible text, so it must be named with `aria-label` or `aria-labelledby`. */
export type ButtonProps = ButtonBaseProps &
  (
    | { size?: Exclude<ButtonSize, 'icon'>; 'aria-label'?: string; 'aria-labelledby'?: string }
    | { size: 'icon'; 'aria-label': string; 'aria-labelledby'?: string }
    | { size: 'icon'; 'aria-label'?: string; 'aria-labelledby': string }
  );

function Spinner({ overlay }: { overlay?: boolean }): JSX.Element {
  return (
    <svg className={cx(styles.spinner, overlay && styles.spinnerOverlay)} viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
      <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2.5" opacity="0.25" />
      <path d="M21 12a9 9 0 0 0-9-9" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
    </svg>
  );
}

/** An icon component (Tabler icons are forwardRef objects) or a raw <svg>. */
function isIcon(node: ReactNode): boolean {
  if (!isValidElement(node)) return false;
  return node.type === 'svg' || typeof node.type === 'function' || (typeof node.type === 'object' && node.type !== null);
}

/**
 * While pending, the spinner takes the leading icon's place. Without a leading icon, the content stays in the layout
 * (transparent, still in the accessibility tree) so the button keeps its width, and the spinner sits on top, centred.
 */
function withSpinner(content: ReactNode): ReactNode {
  const items = Children.toArray(content);
  if (items.length > 0 && isIcon(items[0])) {
    return (
      <>
        <Spinner />
        {items.slice(1)}
      </>
    );
  }
  return (
    <>
      <Spinner overlay />
      <span className={styles.pendingContent}>{content}</span>
    </>
  );
}

/**
 * A button for actions. Built on React Aria's Button, so it handles press events across mouse, touch and keyboard,
 * and `isPending` keeps it focusable while blocking presses.
 *
 * Icons go in `children` (Tabler icons are sized automatically). Full width: pass a className.
 */
export function Button({ variant = 'primary', size = 'md', className, children, isPending, ref, ...rest }: ButtonProps): JSX.Element {
  const local = useRef<HTMLButtonElement | null>(null);
  const setRef = useCallback(
    (el: HTMLButtonElement | null) => {
      local.current = el;
      if (typeof ref === 'function') return ref(el);
      if (ref) ref.current = el;
    },
    [ref],
  );
  // React Aria keeps a pending button focusable (aria-disabled) but doesn't pass aria-busy through, so set it here.
  useLayoutEffect(() => {
    const el = local.current;
    if (!el) return;
    if (isPending) el.setAttribute('aria-busy', 'true');
    else el.removeAttribute('aria-busy');
  }, [isPending]);
  return (
    <RACButton
      {...rest}
      ref={setRef}
      isPending={isPending}
      data-variant={variant}
      data-size={size}
      className={composeRenderProps(className, (c) => cx(styles.root, c))}
    >
      {composeRenderProps(children, (content, { isPending: pending }) => (pending ? withSpinner(content) : content))}
    </RACButton>
  );
}

/*
 * Button — tokens only. Variant and size come from data attributes so consumers can target them too.
 * --_bg / --_fg / --_border are private per-variant hooks; states swap them rather than re-declaring properties.
 */

.root {
  --_bg: transparent;
  --_fg: var(--strata-color-text-default);
  --_border: transparent;
  --_icon: var(--strata-space-4);

  position: relative;
  box-sizing: border-box;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: var(--strata-space-2);
  block-size: var(--strata-control-height);
  min-inline-size: 0;
  margin: 0;
  padding-block: 0;
  padding-inline: var(--strata-control-padding-inline);
  border: 1px solid var(--_border);
  border-radius: var(--strata-radius-button);
  background-color: var(--_bg);
  color: var(--_fg);
  font-family: inherit;
  font-size: var(--strata-font-size-md);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-tight);
  letter-spacing: inherit;
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  outline: none;
}

.root[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}

/* Icons in children: fixed optical size per button size, never squashed. */
.root > svg,
.pendingContent > svg {
  flex: none;
  inline-size: var(--_icon);
  block-size: var(--_icon);
}

/* Arrows and chevrons point "forward", whichever way forward is. */
:is(.root, .pendingContent) > :is([data-directional], :global([class*='tabler-icon-arrow']), :global([class*='tabler-icon-chevron'])):dir(rtl) {
  scale: -1 1;
}

/* ------------------------------------------------------------------ *
 * Variants
 * ------------------------------------------------------------------ */

.root[data-variant='primary'] {
  --_bg: var(--strata-color-action-primary-bg);
  --_fg: var(--strata-color-action-primary-fg);
  --_border: var(--strata-color-action-primary-border);
}
.root[data-variant='primary'][data-hovered] {
  --_bg: var(--strata-color-action-primary-hover);
  --_border: var(--strata-color-action-primary-hover);
}
.root[data-variant='primary'][data-pressed] {
  --_bg: var(--strata-color-action-primary-pressed);
  --_border: var(--strata-color-action-primary-pressed);
}

.root[data-variant='secondary'] {
  --_bg: var(--strata-color-action-secondary-bg);
  --_fg: var(--strata-color-action-secondary-fg);
  /* Secondary fills sit close to the canvas; a same-hue hairline gives the shape an edge. */
  --_border: color-mix(in oklab, var(--strata-color-action-secondary-fg) 16%, transparent);
}
.root[data-variant='secondary'][data-hovered] {
  --_bg: var(--strata-color-action-secondary-hover);
}
.root[data-variant='secondary'][data-pressed] {
  --_bg: var(--strata-color-action-secondary-pressed);
}

.root[data-variant='outline'] {
  --_bg: var(--strata-color-surface-default);
  --_border: var(--strata-color-border-strong);
}
.root[data-variant='outline'][data-hovered] {
  --_bg: color-mix(in oklab, var(--strata-color-text-default) 6%, var(--strata-color-surface-default));
}
.root[data-variant='outline'][data-pressed] {
  --_bg: color-mix(in oklab, var(--strata-color-text-default) 10%, var(--strata-color-surface-default));
}

.root[data-variant='ghost'][data-hovered] {
  --_bg: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
}
.root[data-variant='ghost'][data-pressed] {
  --_bg: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}

.root[data-variant='danger'] {
  --_bg: var(--strata-color-feedback-danger-solid);
  --_fg: var(--strata-color-feedback-danger-on-solid);
  --_border: var(--strata-color-feedback-danger-solid);
}
.root[data-variant='danger'][data-hovered],
.root[data-variant='danger'][data-pressed] {
  /*
   * Darker in both schemes, fill only. color-mix toward text.default darkens in light but lightens in dark
   * (3.9:1 with the white label, below AA) and no role is dark in both schemes, so the fill is multiplied
   * with a translucent layer of itself. Measured ≥ 5.4:1 in every tenant × scheme.
   * Proper fix: a feedback.danger.hover role in the theme engine (like action.primary.hover).
   */
  background-image: linear-gradient(var(--_shade), var(--_shade));
  background-blend-mode: multiply;
  --_shade: color-mix(in oklab, var(--_bg) 35%, transparent);
}
.root[data-variant='danger'][data-pressed] {
  --_shade: color-mix(in oklab, var(--_bg) 60%, transparent);
}

.root[data-variant='link'] {
  --_fg: var(--strata-color-text-brand);
  block-size: auto;
  /* No padding, but still a 24px target (WCAG 2.5.8). */
  min-block-size: var(--strata-space-6);
  padding-inline: 0;
  text-underline-offset: 0.2em;
  text-decoration-thickness: 1px;
}
.root[data-variant='link'][data-hovered] {
  text-decoration-line: underline;
}
.root[data-variant='link'][data-focus-visible] {
  outline-offset: 2px;
  border-radius: min(var(--strata-radius-button), var(--strata-space-1));
}

/* ------------------------------------------------------------------ *
 * Sizes — md is the control height; sm/lg step by one 8px unit.
 * ------------------------------------------------------------------ */

.root[data-size='sm'] {
  --_icon: calc(var(--strata-space-4) - 2px);
  block-size: calc(var(--strata-control-height) - var(--strata-space-2));
  padding-inline: calc(var(--strata-control-padding-inline) - var(--strata-space-1));
  gap: calc(var(--strata-space-2) - 2px);
  font-size: var(--strata-font-size-sm);
}

.root[data-size='lg'] {
  --_icon: calc(var(--strata-space-4) + 2px);
  block-size: calc(var(--strata-control-height) + var(--strata-space-2));
  padding-inline: calc(var(--strata-control-padding-inline) + var(--strata-space-1));
}

.root[data-size='icon'] {
  inline-size: var(--strata-control-height);
  padding-inline: 0;
}

.root[data-variant='link'][data-size] {
  block-size: auto;
  padding-inline: 0;
}

/* ------------------------------------------------------------------ *
 * States
 * ------------------------------------------------------------------ */

.root[data-disabled] {
  --_bg: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
  --_fg: var(--strata-color-text-disabled);
  --_border: transparent;
  cursor: default;
}
.root[data-variant='outline'][data-disabled] {
  --_bg: transparent;
  --_border: var(--strata-color-border-default);
}
.root:is([data-variant='ghost'], [data-variant='link'])[data-disabled] {
  --_bg: transparent;
}

.root[data-pending] {
  cursor: default;
}

.spinner {
  flex: none;
  inline-size: var(--_icon);
  block-size: var(--_icon);
}

/* No leading icon: spinner centred over the (transparent) content so the width never changes. */
.spinnerOverlay {
  position: absolute;
  inset: 0;
  margin: auto;
}

.pendingContent {
  display: contents;
  color: transparent;
}

@media (prefers-reduced-motion: no-preference) {
  .root {
    transition-property: background-color, border-color, color, scale;
    transition-duration: var(--strata-motion-duration-fast);
    transition-timing-function: var(--strata-motion-easing);
  }

  .root[data-pressed]:not([data-variant='link']) {
    scale: 0.98;
  }

  .spinner {
    animation: strata-button-spin calc(var(--strata-motion-duration-normal) * 4) linear infinite;
  }
}

@keyframes strata-button-spin {
  to {
    rotate: 1turn;
  }
}
